#!/usr/bin/env python3
"""Build isolated visual exploration HTML/SVG. Python standard library only; no app imports."""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).resolve().parent
DIRECTIONS = {
 'a': dict(name='Care Journal', idea='Care, kept legible.', core='An attentive editorial journal: a clear next responsibility, followed by source-labelled pages of care.', primary='#254B3E', support='#965442', bg='#F6F2E8', soft='#E6EBDF', ink='#202D27', muted='#56665B', accent='#D9B889', type='Georgia + Noto Naskh Arabic / Noto Sans Arabic fallbacks', shape='Open margins, fine rules and gently softened paper edges', surface='A warm continuous page; only the next responsibility receives a tinted inset', density='Generous patient reading; a two-column clinical casebook with a stable identity margin', icons='Small open-line symbols with full labels; no decorative medical illustrations', patient='Personal, unhurried, readable', doctor='A considered casebook with deliberate writing and review', arabic='Naskh-led reading rhythm; generous line height and sentence-led hierarchy', strength='Calm reading and a clear distinction between the next action and source retrieval.', weakness='Long Arabic passages increase scrolling; the paper metaphor could feel less immediately digital.', risk='Could drift toward premium editorial styling or paper bureaucracy. Dense tables need careful restraint.', distinct='Serif/Naskh display, warm paper, open editorial columns and margin annotations. No permanent sidebar for Patient.'),
 'b': dict(name='Clear Instrument', idea='Every action, in context.', core='A precise clinical instrument: aligned information planes and visible responsibility at each handoff.', primary='#123B60', support='#006875', bg='#EDF2F5', soft='#DBE8F0', ink='#172C3B', muted='#4C6171', accent='#CADF67', type='Existing Inter + existing Noto Sans Arabic', shape='Square geometry, aligned rails, short rectangular indexes', surface='White work planes on a cool field; dark orientation rail and strong table boundaries', density='Compact comparison for Patient; three concurrent panes for dense Doctor tasks', icons='Rectilinear functional glyphs; numbers and text indexes replace illustration', patient='Direct, capable, factual', doctor='A stable workbench for concurrent context, documentation and review', arabic='Sans text with explicit labels; fixed units and names isolated without truncation', strength='Fast scanning of states and exact targets; dense consultation context remains visible.', weakness='Lower warmth; the persistent structure can feel technical, especially on first use.', risk='Could become an enterprise console. Narrow panes require strong Arabic wrapping and reflow.', distinct='Dark side rail, squared work planes, tabular rhythm, three-pane consultation and explicit indexes.'),
 'c': dict(name='Care Thread', idea='Know where care stands.', core='A wayfinding system: distinct stations of responsibility connected by a visible, bounded thread.', primary='#473477', support='#725333', bg='#F5F3FA', soft='#E8E1F2', ink='#29243A', muted='#635B72', accent='#D5C9ED', type='Trebuchet MS / system sans + Noto Kufi Arabic / Noto Sans Arabic fallbacks', shape='Broad round ends, vertical spines and open station markers', surface='Quiet lavender canvas with a continuous white care lane; color is concentrated in orientation', density='Progressive Patient stations; Doctor task spine with an adjacent state ledger', icons='Route/station glyphs that describe navigation, never clinical progress or automated inference', patient='Guided, connected, oriented', doctor='A navigable workspace with visible independent source states', arabic='Kufi display anchors with readable sans body; logical RTL station order', strength='Strong orientation and recognizable movement between related tasks.', weakness='The thread adds visual weight and may suggest a mandatory sequence unless labels stay explicit.', risk='A circle could overpromise completeness; station markers can resemble a progress tracker. No global completion state.', distinct='Horizontal masthead, rounded care lane, station spine, Kufi display and indigo wayfinding.'),
}

# Every direction uses these exact authored synthetic facts. Quantity is a bidi test, never a dose.
FIXTURE = dict(patient='Omar Abdelrahman', ref='EH-DEMO-204', doctor_en='Dr Mariam Hassan', doctor_ar='د. مريم حسن', clinic_en='Dokki Clinic', clinic_ar='عيادة الدقي', date_en='2 November 2026', date_ar='2 نوفمبر 2026', time='14:30', zone='UTC+02:00', medicine='Amoxicillin', quantity='1.25 mL', validity_en='2 November 2026, 14:20 → 5 November 2026, 14:20', summary_en='Your visit summary was shared by Dr Mariam Hassan. Read the recorded instructions in the source.', summary_ar='د. مريم حسن شاركت ملخص الزيارة معاك. اقرأ التعليمات زي ما اتسجّلت في المصدر.')
(ROOT/'evidence'/'synthetic-fixture.json').write_text(json.dumps(FIXTURE,ensure_ascii=False,indent=2)+'\n')

def put(path, content):
 p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(content.replace('↗','<svg class="inline-arrow" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>') if str(path).endswith('.html') else content,encoding='utf-8')
def bdi(value): return f'<bdi dir="ltr">{escape(value)}</bdi>'
def tag(text, kind='info'): return f'<span class="status {kind}">{text}</span>'
def icon(kind):
 paths={'calendar':'M5 4v4m14-4v4M3 10h18M5 6h14a2 2 0 0 1 2 2v12H3V8a2 2 0 0 1 2-2Z', 'page':'M6 3h9l4 4v14H6ZM14 3v5h5M9 12h7m-7 4h7', 'arrow':'m9 5 7 7-7 7', 'search':'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6', 'lock':'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5Z', 'person':'M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 22v-3a8 8 0 0 1 16 0v3'}
 return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="{paths[kind]}"/></svg>'
def mark(code, color='currentColor'):
 # Independent geometric drawings; never sourced from competitor artwork.
 paths={
 'a1':'<path d="M9 13Q22 7 30 15v37Q20 44 9 49Z"/><path d="M35 15Q44 7 56 13v36Q44 44 35 52Z" opacity=".65"/>',
 'a2':'<circle cx="19" cy="15" r="7"/><path d="M7 51V37a12 12 0 0 1 24 0v6H20v-6a1 1 0 0 0-2 0v14Z"/><circle cx="46" cy="49" r="7"/><path d="M58 13v14a12 12 0 0 1-24 0v-6h11v6a1 1 0 0 0 2 0V13Z" opacity=".65"/>',
 'b1':'<path d="M7 9h34v10H7Zm0 18h50v10H7Zm16 18h34v10H23Z"/>',
 'b2':'<path fill-rule="evenodd" d="M7 7h50v15H47v-5H17v30h30v-5h10v15H7Z"/><path d="M27 25h10v14H27Z"/>',
 'c1':'<path d="M48 12A25 25 0 1 0 49 51" fill="none" stroke="'+color+'" stroke-width="10" stroke-linecap="round"/><path d="M38 27h20v10H38Z"/>',
 'c2':'<path d="M10 11h30a15 15 0 0 1 0 30H25v12H10V27h30a2 2 0 0 0 0-4H10Z"/>'}
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="{color}" aria-hidden="true">{paths[code]}</svg>'
LOGOS={
 'a1':('Open folio','Two unequal leaves hold a readable place in care; the open spine signals a bounded source, not a complete chart.','Editorial/publishing overlap; the page silhouette needs recognition testing. No medical-emblem or emergency reading observed.'),
 'a2':('Attentive pair','Two counter-facing human gestures carry attention between people. This is a relationship idea rather than a folio variation.','Social/conversation reading is possible; it must not promise a messaging service. At 16px the open body detail is less distinct.'),
 'b1':('Aligned handoff','Three staggered bars align into a stable exchange: different responsibilities share an order, not unrestricted information.','Generic infrastructure/logistics overlap. Avoid interpreting bars as clinical measurements.'),
 'b2':('Focused frame','An open rectangular boundary holds one exact focal item. The frame is separate from the handoff-bar concept.','Scanning/security-tool association is possible; no monitoring or guaranteed protection claim. Central detail is secondary at 16px.'),
 'c1':('Open interval','An interrupted orbit meets a short independent handoff. The opening deliberately avoids an all-care-complete loop.','Circular/360 category crowding; could imply completeness if paired with careless copy. No arrows or emergency emblem.'),
 'c2':('Folded path','A broad folded route keeps its turn visible and leaves its end open. The solid angular silhouette differs from the open orbit.','Transport/wayfinding overlap and an abstract P reading; not an ECG or pharmacy capsule. Test independent recall.'),
}
for code,(title,why,risk) in LOGOS.items():
 d=DIRECTIONS[code[0]]; col=d['primary']
 svg=mark(code,col).replace(' aria-hidden="true"',' role="img" aria-label="'+code.upper()+' '+title+' exploratory symbol"')
 put(f'logos/{code}-symbol.svg',svg+'\n')
 # SVG proof is a real vector sheet with independent light, dark, mono, app and small-size specimens.
 def nested(x,y,w,c): return f'<svg x="{x}" y="{y}" width="{w}" height="{w}" viewBox="0 0 64 64" fill="{c}">'+mark(code,c).split('>',1)[1].rsplit('</svg>',1)[0]+'</svg>'
 family='Georgia, serif' if code[0]=='a' else ('Arial, sans-serif' if code[0]=='b' else 'Trebuchet MS, sans-serif')
 word=f'<text x="108" y="95" font-family="{family}" font-size="34" font-weight="600">EgyHealth <tspan font-size="23">360</tspan></text>'
 proof=f'''<svg xmlns="http://www.w3.org/2000/svg" width="960" height="340" viewBox="0 0 960 340" role="img" aria-label="{code.upper()} {title}: light and dark wordmark, monochrome, compact and small icon specimens">
<rect width="960" height="340" fill="{d['bg']}"/><text x="28" y="32" fill="{d['ink']}" font-family="Arial" font-size="15">{code.upper()} · {title.upper()} · EXPLORATORY LOGO — NOT FINAL</text>
<g fill="{col}">{nested(28,53,64,col)}{word}</g>
<rect x="496" y="50" width="438" height="94" rx="4" fill="{col}"/>{nested(514,65,64,'#FFFFFF')}<text x="591" y="106" fill="white" font-family="{family}" font-size="30">EgyHealth <tspan font-size="21">360</tspan></text>
<line x1="28" y1="166" x2="934" y2="166" stroke="{col}" opacity=".3"/>
{nested(30,188,64,'#222222')}<text x="112" y="228" fill="#222222" font-family="{family}" font-size="28">EgyHealth 360</text>
<rect x="497" y="184" width="84" height="84" rx="{20 if code[0]!='b' else 4}" fill="{col}"/>{nested(507,194,64,'#FFFFFF')}
{nested(641,193,32,col)}{nested(720,201,16,col)}
<g fill="{d['muted']}" font-family="Arial" font-size="13"><text x="30" y="294">ONE-INK / NO GRADIENT</text><text x="497" y="294">APP ICON</text><text x="630" y="253">32 px</text><text x="708" y="253">16 px</text><text x="28" y="323">Full product name retained. Symbol-only compact use is a specimen, not an approved favicon.</text></g></svg>'''
 put(f'logos/{code}-proof.svg',proof+'\n')


def screen(dkey,kind,ar=False,mobile=False):
 d=DIRECTIONS[dkey]; lang='ar' if ar else 'en'; T=lambda en,artext:artext if ar else en
 patient=bdi(FIXTURE['patient']); doc=T(FIXTURE['doctor_en'],FIXTURE['doctor_ar']); clinic=T(FIXTURE['clinic_en'],FIXTURE['clinic_ar']); date=T(FIXTURE['date_en'],FIXTURE['date_ar']); tm=bdi('14:30'); zone=bdi('UTC+02:00')
 def button(en,arab,primary=False):return f'<button type="button" class="{"primary" if primary else "secondary"}">{T(en,arab)}</button>'
 def heading(en,arab,kicker=''):return f'<div class="page-heading"><div><p class="eyebrow">{kicker}</p><h1>{T(en,arab)}</h1></div><span class="scope">{date}</span></div>'
 def label(en,arab,content):return f'<div class="fact"><span>{T(en,arab)}</span><strong>{content}</strong></div>'
 doctor=kind in ['schedule','consultation','doctor-mobile']
 isconsult=kind=='consultation'
 logo=f'<div class="brand" dir="ltr">{mark(dkey+"1")}<span>EgyHealth <small>360</small></span></div>'
 navlabels=[('Schedule','جدول المواعيد'),('People in your care','مرضاي')] if doctor else [('My care','متابعتي'),('Find care','دور على دكتور')]
 primarynav=''.join(f'<span class="nav-item {"selected" if i==0 else ""}">{icon("calendar" if i==0 else "person")}{T(*n)}</span>' for i,n in enumerate(navlabels))
 account=T('Account · English','الحساب · العربية')
 shell=f'<header class="masthead">{logo}<nav aria-label="{T("Primary navigation","التنقل الأساسي")}">{primarynav}</nav><span class="account">{account}</span></header>'
 title=T('Doctor workspace','مساحة الدكتور') if doctor else T('Your care','رعايتك')
 shell+=f'<div class="scopebar"><span>{title} · {clinic if doctor else patient}</span><span>{T("Visual concept · synthetic data","تصوّر بصري · بيانات افتراضية")}</span></div>'
 retrieval=[('Appointments','مواعيدك'),('Prescriptions','روشتاتك'),('Shared summaries and follow-up','الملخصات والمتابعة'),('Available history','السجل المتاح'),('Your doctors','دكاترتي')]
 retrieval_html=f'<section class="retrieval"><h2>{T("Your available information","معلوماتك المتاحة")}</h2><div>'+''.join(f'<span>{icon("page")}{T(*n)}<span aria-hidden="true">↗</span></span>' for n in retrieval)+'</div></section>'
 appoint=f'''<section class="appointment featured"><p class="eyebrow">{T('NEXT APPOINTMENT','ميعادك الجاي')}</p><div class="appointment-top"><h2>{doc}</h2>{tag(T('Booked','محجوز'),'success')}</div><p class="specialty">{T('Internal medicine','باطنة')} · {clinic}</p><div class="when"><strong>{tm}</strong><div>{date}<br><small>{T('Cairo time','بتوقيت القاهرة')} ({zone})</small></div></div>{button('View appointment','شوف الميعاد',True)}<p class="helper">{T('Booking does not give the doctor access to your medical information.','الحجز لوحده مش بيدي الدكتور صلاحية يشوف معلوماتك الطبية.')}</p></section>'''
 follow=f'''<section class="follow source"><p class="eyebrow">{T('NEXT RESPONSIBILITY','الخطوة الجاية')}</p><h2>{T('Follow-up recommended','الدكتور رشّح لك متابعة')}</h2><p>{T('No appointment is linked to this recommendation here. This recommendation does not book an appointment.','لسه مفيش ميعاد مرتبط بالتوصية هنا. التوصية دي مش حجز ميعاد.')}</p>{button('Find an appointment','دور على ميعاد')}</section>'''
 summary=f'''<section class="summary source"><div class="section-head"><h2>{T('Visit summary','ملخص الزيارة')}</h2>{tag(T('Shared with you','اتشارك معاك'),'info')}</div><p>{T(FIXTURE['summary_en'],FIXTURE['summary_ar'])}</p><div class="source-foot"><span>{doc} · {T('1 November 2026','1 نوفمبر 2026')}</span><strong>{T('Read summary','اقرأ الملخص')} ↗</strong></div></section>'''
 rx=f'''<section class="rx source"><div class="section-head"><h2>{T('Your prescription','روشتتك')}</h2>{tag(T('Prescription signed','الروشتة موقّعة'),'neutral')}</div><p class="medicine">{bdi('Amoxicillin')} <span>{T('Quantity','الكمية')}: {bdi('1.25 mL')}</span></p><p class="helper">{T('Synthetic display quantity, not a dose. Instructions are preserved in the source.','كمية افتراضية لاختبار العرض، مش جرعة. التعليمات محفوظة في المصدر.')}</p><div class="fulfillment"><strong>{T('Accepted by pharmacy','الصيدلية قبلت الروشتة')}</strong><span>{T('No dispense recorded','لسه مفيش صرف متسجل')}</span></div><p class="helper">{T('Acceptance does not confirm medicine availability, pickup readiness or dispense.','القبول مش تأكيد إن الدواء متوفر أو جاهز للاستلام أو إن الصرف اتسجل.')}</p><span class="text-link">{T('View prescription and validity','شوف الروشتة وفترة الصلاحية')} ↗</span></section>'''
 if kind in ['patient','patient-mobile']:
  intro=heading('My care','متابعتي',T('MONDAY · YOUR NEXT STEP','الاتنين · خطوتك الجاية'))
  if dkey=='a':content=intro+f'<div class="journal-layout"><div class="journal-main">{appoint}{summary}{rx}</div><aside>{follow}{retrieval_html}</aside></div>'
  elif dkey=='b':content=intro+f'<div class="instrument-layout"><div class="next-plane"><div class="index-label">01 / {T("CURRENT","الحالي")}</div>{appoint}</div><div class="instrument-sources">{follow}{summary}{rx}</div></div>{retrieval_html}'
  else:content=intro+f'<div class="thread-layout"><div class="care-lane"><div class="station"><span class="station-no">01</span>{appoint}</div><div class="station"><span class="station-no">02</span>{summary}</div><div class="station"><span class="station-no">03</span>{rx}</div></div><aside>{follow}{retrieval_html}<p class="helper">{T("Stations organize available sources, not a complete care timeline.","المحطات بتنظّم المصادر المتاحة، مش سجل كامل للرعاية.")}</p></aside></div>'
 elif kind=='appointment':
  content=heading('Your appointment','ميعادك',T('MY CARE / APPOINTMENT','متابعتي / الميعاد'))+f'<div class="detail-layout">{appoint}<section class="detail-notes source"><h2>{T("Before your visit","قبل زيارتك")}</h2>{label("Doctor","الدكتور",doc)}{label("Clinic","العيادة",clinic)}{label("Location","المكان",T("Dokki, Giza · synthetic clinic","الدقي، الجيزة · عيادة افتراضية"))}{label("Duration","المدة",T("30 minutes","30 دقيقة"))}<hr><h2>{T("Care permission is separate","السماح بالرعاية منفصل")}</h2><p>{T("New care access needs your authorization and doctor acceptance. Booking alone gives no medical access.","طلب الرعاية الجديد محتاج سماحك وقبول الدكتور. الحجز لوحده مش بيدي صلاحية طبية.")}</p>{button("Your doctors","دكاترتي")}<hr>{button("Change appointment","غيّر الميعاد")}{button("Cancel appointment","الغي الحجز")}<p class="helper">{T("A failed change keeps the original appointment.","لو تغيير الميعاد ما نجحش، الميعاد الأصلي هيفضل زي ما هو.")}</p></section></div>'
 elif kind in ['schedule','doctor-mobile']:
  rows=[('13:30','Nour Mostafa',T('Consultation closed','الاستشارة اتقفلت'),'neutral'),('14:00','Salma Ibrahim',T('Booked','محجوز'),'info'),('14:30','Omar Abdelrahman',T('Consultation in progress','الاستشارة جارية'),'success'),('15:00','Youssef Mahmoud',T('Booked','محجوز'),'info'),('15:30','Hana Mohamed',T('Appointment cancelled','الحجز اتلغى'),'neutral')]
  agenda=''.join(f'<div class="visit-row {"current" if n==FIXTURE["patient"] else ""}"><time>{bdi(t)}</time><div><strong>{bdi(n)}</strong><small>{clinic} · {T("30 min","30 دقيقة")}</small></div>{tag(st,k)}<span class="text-link">{T("Continue consultation","كمّل الاستشارة") if n==FIXTURE["patient"] else T("View appointment","شوف الميعاد")} ↗</span></div>' for t,n,st,k in rows)
  current=f'<section class="current-visit"><p class="eyebrow">{T("CURRENT VISIT","الزيارة الحالية")}</p><h2>{patient}</h2><p>{date} · {tm}<br>{T("Cairo time","بتوقيت القاهرة")} ({zone})</p>{tag(T("Active care access","صلاحية الرعاية نشطة"),"success")}<p>{T("Clinical access is checked separately from booking.","صلاحية الرعاية بتتراجع بشكل منفصل عن الحجز.")}</p>{button("Continue consultation","كمّل الاستشارة",True)}</section>'
  content=heading('Schedule','جدول المواعيد',doc)+f'<div class="date-tools"><span>{T("Today","النهارده")} · {date} · {T("Cairo time","بتوقيت القاهرة")} ({zone})</span>{button("Manage availability","نظّم المواعيد المتاحة")}</div>'
  if dkey=='a':content+=f'<div class="schedule-journal"><section class="agenda">{agenda}</section><aside>{current}<p class="margin-note">{T("The schedule shows logistics. It never grants medical access.","الجدول بيعرض المواعيد. ظهوره مش بيدي صلاحية طبية.")}</p></aside></div>'
  elif dkey=='b':content+=f'<div class="schedule-grid"><section class="agenda"><div class="table-title">{T("TIME / PERSON / VISIT STATE","التوقيت / المريض / حالة الزيارة")}</div>{agenda}</section><aside>{current}</aside></div>'
  else:content+=f'{current}<section class="agenda station-agenda"><h2>{T("Today’s appointments","مواعيد النهارده")}</h2>{agenda}</section>'
  content+=f'<p class="helper">{T("Closed consultation does not mean all content was shared. Attendance is recorded by a doctor, never inferred from elapsed time.","قفل الاستشارة مش معناه إن كل المحتوى اتشارك. الدكتور بيسجّل الحضور؛ مرور الوقت لوحده مش دليل.")}</p>'
 elif kind=='consultation':
  identity=f'<section class="identity"><div><p class="eyebrow">{T("ACTIVE CONSULTATION","الاستشارة الحالية")}</p><h1>{patient}</h1><p>{T("Synthetic reference","مرجع افتراضي")}: {bdi("EH-DEMO-204")} · {clinic} · {doc}</p></div><div>{tag(T("Consultation open","الاستشارة مفتوحة"),"info")}{tag(T("Active care access","صلاحية الرعاية نشطة"),"success")}<p>{date} · {tm} · {zone}</p></div></section>'
  tasks=[('Review & documentation','المراجعة والتوثيق'),('Prescription & pharmacy','الوصفة الطبية والصيدلية'),('Follow-up','المتابعة'),('Review & close','المراجعة والإغلاق')]
  tasknav='<nav class="local-tasks" aria-label="'+T('Consultation tasks','مهام الاستشارة')+'">'+''.join(f'<span class="{"active" if i==0 else ""}"><small>{i+1:02}</small>{T(*n)}</span>' for i,n in enumerate(tasks))+'</nav>'
  context=f'<section class="clinical-context"><h2>{T("Clinical context","سياق الرعاية")}</h2>{label("Visit reason","سبب الزيارة",T("Recorded follow-up visit","زيارة متابعة مسجّلة"))}<div class="notice warning"><strong>! {T("Allergies: not reviewed","الحساسية: لسه ما اتراجعتش")}</strong><p>{T("Not reviewed does not mean no known allergies.","عدم المراجعة مش معناه إن مفيش حساسية معروفة.")}</p></div>{label("Source history","سجل المصدر",T("Available sources only","المصادر المتاحة بس"))}{label('Recorded BP','الضغط المسجّل',bdi('128/82 mmHg'))}{label('Recorded pulse','النبض المسجّل',bdi('72 bpm'))}<p class="helper">{T("Synthetic observations; no interpretation. Other authors’ private notes are excluded.","قياسات افتراضية من غير تفسير. الملاحظات الخاصة بمؤلفين تانيين مش معروضة.")}</p></section>'
  editor=f'''<section class="editor"><div class="section-head"><h2>{icon('lock')}{T('Private note','ملاحظة خاصة')}</h2>{tag(T('Draft saved · 14:42','المسودة اتحفظت · 14:42'),'neutral')}</div><p class="helper">{T('Only the permitted author can read this note. Signing keeps it private.','المؤلف المسموح له بس يقدر يقرأ الملاحظة. التوقيع مش بيشاركها مع المريض.')}</p><label for="note">{T('Recorded findings','الملاحظات المسجّلة')}</label><textarea id="note" readonly>{T('Synthetic recorded note: patient attended to review previously shared instructions. Medication history has not been reconciled in this example. Allergy review remains pending. No automated assessment.','ملاحظة افتراضية مسجّلة: المريض حضر لمراجعة التعليمات اللي اتشاركت قبل كده. قائمة الأدوية لسه ما اتراجعتش في المثال ده. مراجعة الحساسية لسه معلّقة. مفيش تقييم تلقائي.')}</textarea><div class="actions">{button('Save draft','احفظ المسودة')}{button('Review private-note signing','راجع توقيع الملاحظة الخاصة')}</div><hr><div class="section-head"><h2>{T('Visit summary','ملخص الزيارة')}</h2>{tag(T('Signed and shared','اتوقّع واتشارك'),'success')}</div><p>{T('This summary is visible to the patient. Private notes remain private.','المريض يقدر يقرأ الملخص ده. الملاحظات الخاصة هتفضل خاصة.')}</p><small>{doc} · {date} · {bdi('14:40')} {zone}</small><hr><div class="section-head"><h2>{T('Follow-up recommendation','المتابعة المقترحة')}</h2>{tag(T('Signed and shared','اتوقّعت واتشاركت'),'info')}</div><p>{T('No appointment is linked here. A recommendation does not book a visit.','لسه مفيش ميعاد مرتبط هنا. التوصية مش بتحجز ميعاد.')}</p></section>'''
  prescription=f'''<section class="prescription"><div class="section-head"><h2>{T('Prescription','الوصفة الطبية')}</h2>{tag(T('Signed','موقّعة'),'neutral')}</div><h3>{bdi('Amoxicillin')}</h3>{label('Quantity / unit','الكمية / الوحدة',bdi('1.25 mL'))}<p class="helper">{T('Synthetic quantity for display testing, not a dose.','كمية افتراضية لاختبار العرض، مش جرعة.')}</p>{label('Valid from','سارية من',f'{date} · {bdi("14:20")} {zone}')}{label('Valid until','سارية لحد',f'{T("5 November 2026","5 نوفمبر 2026")} · {bdi("14:20")} {zone}')}<p>{T('Instructions retained exactly in the signed source.','التعليمات محفوظة زي ما اتسجّلت في المصدر الموقّع.')}</p><hr>{label('Pharmacy responsibility','مسؤولية الصيدلية',T('Accepted by pharmacy','الصيدلية قبلت الوصفة الطبية'))}{label('Recorded supply','الصرف المسجّل',T('No dispense recorded','لسه مفيش صرف متسجل'))}<p class="helper">{T('Signing, pharmacy acceptance and actual dispense are separate. Availability is not confirmed.','التوقيع وقبول الصيدلية والصرف الفعلي حالات منفصلة. توفر الدواء مش مؤكد.')}</p></section>'''
