 fields=[('Core idea',d['core']),('Visual personality',d['idea']),('Logo family',f'{key.upper()}1 {LOGOS[key+"1"][0]} + {key.upper()}2 {LOGOS[key+"2"][0]} — equal exploration candidates'),('Shape language',d['shape']),('Surface philosophy',d['surface']),('Information density',d['density']),('Color philosophy',{'a':'Forest identity on warm paper; clay marks editorial attention. Functional states keep their independent meanings.','b':'Deep blue orientation, cool work planes, teal support and a small lime index accent. Accent is never a clinical success signal.','c':'Indigo wayfinding over lavender neutrals; warm brown source annotations. A visible station is not a completed clinical step.'}[key]),('Typography philosophy',d['type']+' — exploratory only; no final family.'),('Icon / illustration philosophy',d['icons']),('Patient experience feel',d['patient']),('Doctor experience feel',d['doctor']),('Arabic fit',d['arabic']),('Strengths',d['strength']),('Weaknesses',d['weakness']),('Risks',d['risk']),('What makes this distinct',d['distinct'])]
